// Generated by scripts/stdlib.mjs from lib/. Do not edit.

export const LIBRARIES: Record<string, string> = {
  "kerf/box": "// kerf/box: finger-jointed boxes.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// Box from its outer size [width, depth, height] in the current material.\n// Edges pair \"out\" with \"in\", and the bottom owns every bottom corner,\n// so the six panels interlock without gaps.\nmodule box(size, lid = false, finger = undef) {\n  w = size[0];\n  d = size[1];\n  h = size[2];\n  t = $thickness;\n  top = lid ? \"in\" : \"flat\";\n  part(\"bottom\", at = [0, 0, 0]) finger_rect([w, d], \"out\", finger = finger);\n  if (lid) part(\"lid\", at = [0, 0, h - t]) finger_rect([w, d], \"out\", finger = finger);\n  part(\"front\", at = [0, t, 0], rotate = [90, 0, 0])\n    finger_rect([w, h], [\"in\", \"out\", top, \"out\"], finger = finger);\n  part(\"back\", at = [0, d, 0], rotate = [90, 0, 0])\n    finger_rect([w, h], [\"in\", \"out\", top, \"out\"], finger = finger);\n  part(\"left\", rotate = [90, 0, 90])\n    finger_rect([d, h], [\"in\", \"in\", top, \"in\"], finger = finger);\n  part(\"right\", at = [w - t, 0, 0], rotate = [90, 0, 90])\n    finger_rect([d, h], [\"in\", \"in\", top, \"in\"], finger = finger);\n}\n\n// Divider that slides between two walls: tabs on both sides drop into\n// finger_holes() cut in the walls.\nmodule divider(size, finger = undef) {\n  finger_rect(size, [\"flat\", \"out\", \"flat\", \"out\"], finger = finger);\n}\n",
  "kerf/calibration": "// kerf/calibration: test pieces that measure your laser and your sheet,\n// before you cut a design that depends on them. The labels are text, so\n// they need a font; turn them off with labels = false.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// Kerf gauge: a frame and `strips` strips inside it, all separated by\n// single cuts, which kerf compensation does not move. Push the strips to\n// one side and measure the gap they leave: the kerf is the gap divided by\n// strips + 1. `size` is the window the strips fill.\nmodule kerf_gauge(strips = 10, size = [60, 25], labels = true) {\n  foot = labels ? 12 : 6;\n  w = size[0] + 12;\n  rect([w, size[1] + 6 + foot], r = 2);\n  translate([6, foot]) {\n    outline() rect(size);\n    for (i = [1:strips - 1]) line([size[0] * i / strips, 0], [size[0] * i / strips, size[1]]);\n  }\n  if (labels)\n    engrave() translate([w / 2, 4]) text(str(\"kerf = gap / \", strips + 1), size = 3.5, halign = \"center\");\n}\n\n// Slot gauge: `steps` slots `depth` deep, from narrower than $thickness\n// to wider by `step` each, labelled with the difference. Try a scrap of\n// the same sheet in each: the one that fits as you want is the clearance\n// to add to slots.\nmodule slot_gauge(steps = 7, step = 0.1, depth = 15, labels = true) {\n  pitch = $thickness + 8;\n  deltas = [for (i = [0:steps - 1]) round((i - (steps - 1) / 2) * step * 100) / 100];\n  difference() {\n    rect([steps * pitch + 4, depth + 12], r = 2);\n    for (i = [0:steps - 1])\n      translate([pitch / 2 + 2 + i * pitch - ($thickness + deltas[i]) / 2, 12])\n        rect([$thickness + deltas[i], depth + 1]);\n  }\n  if (labels)\n    engrave() for (i = [0:steps - 1])\n      translate([pitch / 2 + 2 + i * pitch, 4])\n        text(str(deltas[i] > 0 ? \"+\" : \"\", deltas[i]), size = 3.5, halign = \"center\");\n}\n\n// Finger joint test: a pair of pieces for each kerf in `kerfs`, cut with\n// that kerf compensation, as parts \"joint <kerf> out\" and \"joint <kerf>\n// in\". Push each pair together: the kerf of the pair that holds without\n// glue and without forcing is the one to set for this sheet.\nmodule joint_test(kerfs = [0.1, 0.15, 0.2], size = [40, 20], finger = undef, labels = true) {\n  for (k = kerfs) {\n    $kerf = k;\n    for (edge = [\"out\", \"in\"])\n      part(str(\"joint \", k, \" \", edge)) {\n        finger_rect(size, [edge, \"flat\", \"flat\", \"flat\"], finger = finger);\n        if (labels)\n          engrave() translate([size[0] / 2, (size[1] + $thickness) / 2])\n            text(str(k), size = 4, halign = \"center\", valign = \"center\");\n      }\n  }\n}\n",
  "kerf/dividers": "// kerf/dividers: dividers that slot into each other like an egg crate.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// A divider `length` long and `height` tall, with a slot half its height\n// at each x in `at` for a divider that crosses it: from the top, or from\n// the bottom with from = \"bottom\". Two crossing dividers take one of\n// each. `scoops` dips in the top edge, evenly spaced, make room for a\n// finger; `clearance` is added to the slot width.\nmodule slotted_divider(length, height, at = [], from = \"top\", clearance = 0.15, scoops = 0) {\n  s = $thickness + clearance;\n  difference() {\n    rect([length, height], r = 1);\n    if (scoops > 0)\n      for (k = [0:scoops - 1])\n        translate([length * (k + 0.5) / scoops, height])\n          ellipse([min(length / scoops * 0.3, 30), height * 0.35], $fn = 64);\n    for (x = at) translate([x - s / 2, from == \"top\" ? height / 2 : -1]) rect([s, height / 2 + 1]);\n  }\n}\n\n// A grid of dividers for the inside of a box or drawer, `size` =\n// [width, depth, height], making `cols` compartments across and `rows`\n// front to back. The parts \"long divider\" run left to right and \"cross\n// divider\" front to back. They stop `gap` short of the walls, and stand\n// in the assembly with the inside's front left bottom corner at `at`.\nmodule grid_dividers(size, cols = 2, rows = 2, clearance = 0.15, gap = 0.5, scoops = false, at = [0, 0, 0]) {\n  t = $thickness;\n  w = size[0];\n  d = size[1];\n  h = size[2];\n  if (rows > 1)\n    part(\"long divider\", qty = rows - 1, rotate = [90, 0, 0],\n      at = [for (i = [1:rows - 1]) at + [gap, d * i / rows + t / 2, 0]])\n      slotted_divider(w - 2 * gap, h, cols > 1 ? [for (j = [1:cols - 1]) w * j / cols - gap] : [],\n        \"top\", clearance, scoops ? cols : 0);\n  if (cols > 1)\n    part(\"cross divider\", qty = cols - 1, rotate = [90, 0, 90],\n      at = [for (j = [1:cols - 1]) at + [w * j / cols - t / 2, gap, 0]])\n      slotted_divider(d - 2 * gap, h, rows > 1 ? [for (i = [1:rows - 1]) d * i / rows - gap] : [],\n        \"bottom\", clearance, scoops ? rows : 0);\n}\n",
  "kerf/enclosure": "// kerf/enclosure: boxes with a screwed-on lid, for electronics and parts\n// you need to get back to.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// Box with a lid held by screws. The walls and the bottom are finger\n// jointed, as box() in kerf/box; the lid lies on the walls and overhangs\n// them by `lip`, and each screw goes through it into the top of the front\n// or back wall, into a nut in a T-slot. `size` is the outside [width,\n// depth, height], lid included. `screw` is the diameter and\n// `screw_length` the length under the head; `nut` is [width, height] of\n// the nut's slot. `cutouts` lists holes in the panels, see\n// enclosure_cutouts().\nmodule enclosure(size, screw = 3, screw_length = 12, nut = undef, lip = undef, cutouts = [], finger = undef) {\n  t = $thickness;\n  o = is_undef(lip) ? screw : lip;\n  // The box under the lid\n  w = size[0] - 2 * o;\n  d = size[1] - 2 * o;\n  h = size[2] - t;\n  into = screw_length - t;\n  nut_slot = is_undef(nut) ? [screw * 1.9, screw * 0.9] : nut;\n  assert(into > nut_slot[1], \"screw_length is too short for the lid and the nut\");\n  assert(h > into + 2 * t, \"the walls are too low for the screws\");\n  // Two screws on the front and the back, and one more for every 80 mm\n  n = max(2, round(w / 80));\n  xs = [for (i = [0:n - 1]) w * (i + 0.5) / n];\n  part(\"bottom\", at = [o, o, 0]) difference() {\n    finger_rect([w, d], \"out\", finger = finger);\n    enclosure_cutouts(\"bottom\", cutouts);\n  }\n  part(\"lid\", at = [0, 0, h]) difference() {\n    rect([w + 2 * o, d + 2 * o]);\n    for (x = xs, y = [t / 2, d - t / 2]) translate([o + x, o + y]) circle(d = screw + 0.3, $fn = 24);\n    enclosure_cutouts(\"lid\", cutouts);\n  }\n  part(\"front\", at = [o, o + t, 0], rotate = [90, 0, 0]) difference() {\n    finger_rect([w, h], [\"in\", \"out\", \"flat\", \"out\"], finger = finger);\n    for (x = xs) translate([x, h]) rotate(180) tslot(screw, into, nut_slot);\n    enclosure_cutouts(\"front\", cutouts);\n  }\n  part(\"back\", at = [o, o + d, 0], rotate = [90, 0, 0]) difference() {\n    finger_rect([w, h], [\"in\", \"out\", \"flat\", \"out\"], finger = finger);\n    for (x = xs) translate([x, h]) rotate(180) tslot(screw, into, nut_slot);\n    enclosure_cutouts(\"back\", cutouts);\n  }\n  part(\"left\", at = [o, o, 0], rotate = [90, 0, 90]) difference() {\n    finger_rect([d, h], [\"in\", \"in\", \"flat\", \"in\"], finger = finger);\n    enclosure_cutouts(\"left\", cutouts);\n  }\n  part(\"right\", at = [o + w - t, o, 0], rotate = [90, 0, 90]) difference() {\n    finger_rect([d, h], [\"in\", \"in\", \"flat\", \"in\"], finger = finger);\n    enclosure_cutouts(\"right\", cutouts);\n  }\n}\n\n// The holes listed in `cutouts` for one panel. Each is [side, [x, y],\n// size]: side is \"front\", \"back\", \"left\", \"right\", \"lid\" or \"bottom\";\n// [x, y] is the hole's centre on the panel as it is drawn, from its\n// bottom left corner; a number size is a round hole of that diameter, and\n// [width, height] a rectangle. Add \"vents\" after the size for vents()\n// filling that rectangle.\nmodule enclosure_cutouts(side, cutouts) {\n  for (c = cutouts)\n    if (c[0] == side) translate(c[1]) {\n      if (c[3] == \"vents\") vents(c[2]);\n      else if (is_list(c[2])) rect(c[2], center = true);\n      else circle(d = c[2]);\n    }\n}\n\n// Ventilation slots across [width, height], centred on the origin:\n// upright slots `slot` wide with round ends, `pitch` apart.\nmodule vents(size, slot = 3, pitch = 6) {\n  n = max(1, floor((size[0] - slot) / pitch) + 1);\n  ends = max(0, size[1] - slot) / 2;\n  for (i = [0:n - 1])\n    translate([(i - (n - 1) / 2) * pitch, 0]) hull() {\n      translate([0, -ends]) circle(d = slot, $fn = 24);\n      translate([0, ends]) circle(d = slot, $fn = 24);\n    }\n}\n",
  "kerf/hanging": "// kerf/hanging: holes, keyholes and loops for hanging things on a wall.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n//\n// Each module cuts its hole out of the shapes it is given, as in\n// keyhole([0, 40]) rect([100, 50]). Given nothing, it makes the hole\n// itself, to subtract in a difference() of your own.\n\n// A keyhole for hanging on a screw: the head goes through the round hole,\n// then the panel drops `drop` mm so the screw rests at `at`, at the top of\n// the slot. `head` and `shank` are the hole and slot widths; measure the\n// screw and add a little.\nmodule keyhole(at = [0, 0], head = 9, shank = 4.5, drop = 10) {\n  assert(drop >= (head + shank) / 2, \"drop must be at least (head + shank) / 2\");\n  module hole() translate(at) {\n    translate([0, -drop]) circle(d = head);\n    hull() {\n      circle(d = shank);\n      translate([0, -drop]) circle(d = shank);\n    }\n  }\n  if ($children > 0) difference() { children(); hole(); } else hole();\n}\n\n// Two keyholes `spacing` apart, centred on `at`, for a panel that hangs\n// level and does not turn.\nmodule keyholes(spacing, at = [0, 0], head = 9, shank = 4.5, drop = 10) {\n  module holes() for (x = [-spacing / 2, spacing / 2]) keyhole(at + [x, 0], head, shank, drop);\n  if ($children > 0) difference() { children(); holes(); } else holes();\n}\n\n// A round hole of diameter `d` at `at`, for a nail, a hook or a cord.\n// Give `spacing` for two holes that far apart, centred on `at`.\nmodule hanging_hole(at = [0, 0], d = 5, spacing = 0) {\n  module holes() for (x = spacing > 0 ? [-spacing / 2, spacing / 2] : [0])\n    translate(at + [x, 0]) circle(d = d);\n  if ($children > 0) difference() { children(); holes(); } else holes();\n}\n\n// A ring around a hole of diameter `d` at `at`, `wall` wide, joined to the\n// shapes it is given: put it on the edge of an ornament or a tag, and the\n// hole stays open even where the ring overlaps the shape.\nmodule hanging_loop(at = [0, 0], d = 4, wall = 3) {\n  difference() {\n    union() {\n      children();\n      translate(at) circle(d = d + 2 * wall);\n    }\n    translate(at) circle(d = d);\n  }\n}\n",
  "kerf/hinge": "// kerf/hinge: living hinges, for bending flat sheet around a corner.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\nuse <kerf/tabs>\n\n// Length of living hinge that bends `angle` degrees around an inside\n// radius `r`: the arc along the middle of the sheet.\nfunction bend_length(r, angle = 90) = PI * (r + $thickness / 2) * angle / 180;\n\n// A rectangle that bends: a living hinge across its full height at each x\n// in `bends`, centred there and `width` wide. The width defaults to a\n// 90° bend around three thicknesses; `r` rounds the corners.\nmodule flex_rect(size, bends, width = undef, spacing = 1.5, bridge = 3, r = 0) {\n  w = is_undef(width) ? bend_length(3 * $thickness) : width;\n  rect(size, r = r);\n  for (x = bends)\n    translate([x - w / 2, 0]) living_hinge([w, size[1]], spacing = spacing, bridge = bridge);\n}\n\n// Box with rounded corners whose four sides are one strip, bent at the\n// corners by living hinges. The bottom's tabs go through slots in the\n// strip; the lid rests on top, kept in place by an insert glued under it.\n// `size` is the outside [width, depth, height], lid included, and `r` the\n// outside corner radius, more than two thicknesses.\nmodule flex_box(size, r = 15, lid = true, clearance = 0.1, spacing = 1.5, bridge = 3) {\n  t = $thickness;\n  w = size[0];\n  d = size[1];\n  h = lid ? size[2] - t : size[2];\n  assert(r > 2 * t, \"r must be more than two thicknesses\");\n  assert(w >= 2 * r && d >= 2 * r, \"width and depth must be at least 2 * r\");\n  // Straight runs and the bends at the corners, measured along the strip\n  sw = w - 2 * r;\n  sd = d - 2 * r;\n  b = bend_length(r - t);\n  L = 2 * sw + 2 * sd + 4 * b;\n  // The strip starts in the middle of the front and goes round\n  // anticlockwise seen from above: where each run starts, and its length\n  runs = [[-sw / 2, sw], [sw / 2 + b, sd], [sw / 2 + 2 * b + sd, sw], [1.5 * sw + 3 * b + sd, sd]];\n  bends = [sw / 2 + b / 2, sw / 2 + 1.5 * b + sd, 1.5 * sw + 2.5 * b + sd, 1.5 * sw + 3.5 * b + 2 * sd];\n  part(\"side\") difference() {\n    flex_rect([L, h], bends, width = b, spacing = spacing, bridge = bridge);\n    // The front run crosses the ends: its slots are cut at both\n    for (run = runs, o = [0, L])\n      if (run[1] > 0) translate([run[0] + o, 1.5 * t]) slots(run[1], clearance = clearance);\n  }\n  part(\"bottom\") flex_panel([w - 2 * t, d - 2 * t], r - t, sw, sd);\n  if (lid) {\n    part(\"lid\") rect([w, d], r = r);\n    part(\"lid insert\")\n      offset(delta = -clearance) rect([w - 2 * t, d - 2 * t], r = r - t);\n  }\n}\n\n// The bottom of flex_box(): a rounded rectangle with tabs on its straight\n// runs, `sw` long on the front and back and `sd` on the sides.\nmodule flex_panel(size, r, sw, sd) {\n  rect(size, r = r);\n  if (sw > 0) {\n    translate([r, 0]) tabs(sw);\n    translate([r + sw, size[1]]) rotate(180) tabs(sw);\n  }\n  if (sd > 0) {\n    translate([size[0], r]) rotate(90) tabs(sd);\n    translate([0, r + sd]) rotate(270) tabs(sd);\n  }\n}\n",
  "kerf/tabs": "// kerf/tabs: tab and slot joints, for one panel standing on another.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// Centres of `count` tabs spread evenly along an edge `length` long.\n// Without a count, one tab for every 50 mm, and at least one.\nfunction tab_positions(length, count = undef) =\n  let (n = is_undef(count) ? max(1, round(length / 50)) : count)\n  n < 1 ? assert(false, \"count must be at least 1\") :\n  [for (i = [0:n - 1]) length * (i + 0.5) / n];\n\n// Tabs along x from 0 to `length`, hanging `depth` below y = 0: join them\n// to the bottom edge of a panel, and cut slots() where they go through.\n// Each tab is `width` wide, half the space between tabs by default, and\n// `depth` defaults to $thickness, flush with the far side.\nmodule tabs(length, count = undef, width = undef, depth = undef) {\n  at = tab_positions(length, count);\n  w = is_undef(width) ? length / (2 * len(at)) : width;\n  h = is_undef(depth) ? $thickness : depth;\n  for (x = at) translate([x - w / 2, -h]) rect([w, h]);\n}\n\n// The slots that tabs() with the same length, count and width go\n// through, centred on y = 0. `clearance` is added to the width and to\n// $thickness, so the tabs slide in.\nmodule slots(length, count = undef, width = undef, clearance = 0.1) {\n  at = tab_positions(length, count);\n  w = is_undef(width) ? length / (2 * len(at)) : width;\n  for (x = at) translate([x, 0]) rect([w + clearance, $thickness + clearance], center = true);\n}\n\n// A rectangle with tabs on some of its edges, outside `size`. `edges` is\n// true or false for all four, or [bottom, right, top, left].\nmodule tab_rect(size, edges = true, count = undef, width = undef) {\n  e = is_list(edges) ? edges : [edges, edges, edges, edges];\n  w = size[0];\n  h = size[1];\n  rect([w, h]);\n  if (e[0]) tabs(w, count, width);\n  if (e[1]) translate([w, 0]) rotate(90) tabs(h, count, width);\n  if (e[2]) translate([w, h]) rotate(180) tabs(w, count, width);\n  if (e[3]) translate([0, h]) rotate(270) tabs(h, count, width);\n}\n"
};
